use std::{sync::{Arc,atomic::{AtomicBool,Ordering}},time::Duration};
extern "C" {fn mallopt(param:i32,value:i32)->i32;}
#[test] fn arena_limited_thread_pressure(){assert_eq!(unsafe{mallopt(-8,1)},1);let stop=Arc::new(AtomicBool::new(false));let mut joins=Vec::new();for _ in 0..200 {let s=stop.clone();joins.push(std::thread::Builder::new().stack_size(131072).spawn(move||{let v=vec![1u8;4096];while !s.load(Ordering::Relaxed){std::thread::sleep(Duration::from_millis(5))}std::hint::black_box(v);}).unwrap());}std::thread::sleep(Duration::from_millis(100));let status=std::fs::read_to_string("/proc/self/status").unwrap();let line=status.lines().find(|l|l.starts_with("VmSize:")).unwrap();let n:usize=line.split_whitespace().nth(1).unwrap().parse().unwrap();println!("{line}; workers={}",joins.len());stop.store(true,Ordering::Relaxed);for j in joins {j.join().unwrap()}assert!(n<200_000,"{line}");}